<script setup>
import{provide}from'vue';import{useClipboard}from'./use-clipboard.js';import History from'./views/History.vue';import Search from'./views/Search.vue';import Settings from'./parts/Settings.vue';import Feedback from'./Feedback.vue';const props=defineProps({host:Object,kind:{type:String,default:'history'},popup:{type:Boolean,default:false},settings:{type:Boolean,default:false}}),ui=useClipboard(props.host,props.kind,props.popup&&!props.settings);provide('clipboard-ui',ui);
</script>
<template><History v-if="popup&&kind==='history'"/><Search v-else-if="popup&&!settings"/><section v-else id="clipboard" class="control-card"><h3>{{kind==='history'?'剪切板':'AI 剪切板'}}</h3><p>{{ui.state.status.captureEnabled?'后台采集已启用':'后台采集未启用'}} · {{ui.state.status.shortcutRegistered?'快捷键已注册':'快捷键未注册'}}</p><small v-if="host.preview">预览不读取剪切板、注册快捷键或发送文本。</small><Feedback/><el-button v-if="!settings" :disabled="host.preview||ui.locked.value" @click="ui.run(()=>ui.client.open())">打开{{kind==='history'?'历史记录':'搜索条'}}</el-button><Settings v-if="ui.loaded.value"/></section></template>
<style scoped>.control-card{height:100%;overflow:auto;box-sizing:border-box;border-radius:16px;background:#f5f5ff;color:#161638;padding:12px;font-size:13px}.control-card h3{margin:0 0 8px}.control-card>.settings{padding:12px 0;height:auto}.control-card>p{font-size:12px;margin:6px 0}</style>
